// Esperamos: { lead_id, email, producto, con_instalacion?, mantenimiento? }
// producto: 'pack' | 'crm' | 'informes' | 'chatbot'
// con_instalacion: bool — si true, precio sube
// mantenimiento: bool — añadir suscripción 300€/mes

const body = $input.item.json.body || $input.item.json;
if (!body.email || !body.producto) {
  throw new Error('Faltan campos: email y producto son obligatorios');
}

const PRICE_IDS = {
  pack:               $env.STRIPE_PRICE_PACK || 'price_pack_498',
  pack_install:       $env.STRIPE_PRICE_PACK_INSTALL || 'price_pack_install_1349',
  crm:                $env.STRIPE_PRICE_CRM || 'price_crm_27',
  informes_basic:     $env.STRIPE_PRICE_INFORMES_BASIC || 'price_informes_199',
  informes_pro:       $env.STRIPE_PRICE_INFORMES_PRO || 'price_informes_449',
  chatbot_basic:      $env.STRIPE_PRICE_CHATBOT_BASIC || 'price_chatbot_399',
  chatbot_pro:        $env.STRIPE_PRICE_CHATBOT_PRO || 'price_chatbot_999',
  mantenimiento:      $env.STRIPE_PRICE_MANTENIMIENTO || 'price_mantenimiento_300mo'
};

const lineItems = [];

// Producto principal
if (body.producto === 'pack') {
  lineItems.push({ price: body.con_instalacion ? PRICE_IDS.pack_install : PRICE_IDS.pack, quantity: 1 });
} else if (body.producto === 'crm') {
  lineItems.push({ price: PRICE_IDS.crm, quantity: 1 });
} else if (body.producto === 'informes') {
  lineItems.push({ price: body.tier === 'pro' ? PRICE_IDS.informes_pro : PRICE_IDS.informes_basic, quantity: 1 });
} else if (body.producto === 'chatbot') {
  lineItems.push({ price: body.tier === 'pro' ? PRICE_IDS.chatbot_pro : PRICE_IDS.chatbot_basic, quantity: 1 });
} else {
  throw new Error(`Producto desconocido: ${body.producto}`);
}

// Mantenimiento opcional (suscripción)
if (body.mantenimiento) {
  lineItems.push({ price: PRICE_IDS.mantenimiento, quantity: 1 });
}

return {
  email: body.email.toLowerCase().trim(),
  lead_id: body.lead_id || null,
  producto: body.producto,
  line_items: lineItems,
  has_subscription: !!body.mantenimiento,
  metadata: {
    lead_id: body.lead_id || '',
    producto: body.producto,
    con_instalacion: String(!!body.con_instalacion),
    fuente: 'marli-funnel'
  }
};
